const sourceId = 'office365_shared';
const raw = msg.payload || [];
msg.payload = raw.map(e => ({
    uid:      e.uid || (e.summary + e.start),
    title:    e.summary || '(kein Titel)',
    start:    e.start instanceof Date ? e.start.toISOString() : e.start,
    end:      e.end   instanceof Date ? e.end.toISOString()   : e.end,
    allDay:   e.allDayEvent || false,
    location: e.location || null,
    source:   sourceId
}));
return msg;

// payload ist ein Array von Arrays (eines pro Quelle)
const all = [].concat(...(msg.payload || []));

// Sortieren nach Startzeit, Ganztag-Termine zuerst
all.sort((a, b) => {
    if (a.allDay && !b.allDay) return -1;
    if (!a.allDay && b.allDay) return 1;
    return new Date(a.start) - new Date(b.start);
});

// Aktuellen Profil-Status aus Flow-Kontext lesen (setzt profile/set Handler)
const profile = flow.get('calendar_profile') || null;

msg.payload = { events: all, profile: profile };
msg.topic = 'calendar';
return msg;

// Publiziert an alle konfigurierten Panel-IDs
// Panel-IDs hier anpassen:
const panels = ['kitchen'];

const msgs = panels.map(panelId => ({
    topic:   `dashboard/panels/${panelId}/calendar/state`,
    payload: JSON.stringify(msg.payload),
    qos:     1,
    retain:  true
}));

return [msgs];

if (msg.payload && msg.payload.profile) {
    flow.set('calendar_profile', msg.payload.profile);
    node.log('Kalender-Profil gewechselt: ' + msg.payload.profile);
}
return null;
